function showDialog(title,body,action,label='Continue'){const d=$('dialog');$('dialogTitle').textContent=title;$('dialogBody').innerHTML=body;$('dialogConfirm').textContent=label;$('dialogConfirm').hidden=!action;$('dialogCancel').textContent=action?'Cancel':'Close';$('dialogConfirm').onclick=()=>{d.close();action?.()};if(!d.open)d.showModal()}
