function normalize(){active.m=Math.max(0,Math.min(active.m,song.measures.length-1));if(song.staff!=='grand')active.t=0;if(selected&&!song.measures[selected.m]?.tracks[selected.t]?.[selected.i])selected=null;M.cleanTies(song)}
