function undo(){if(!history.length)return;stop();future.push(M.clone(song));song=history.pop();selected=null;normalize();persist();render()}
function redo(){if(!future.length)return;stop();history.push(M.clone(song));song=future.pop();selected=null;normalize();persist();render()}
function current(){return selected?song.measures[selected.m]?.tracks[selected.t]?.[selected.i]:null}
function tracks(){return song.staff==='grand'?[0,1]:[0]}
