 const formatter=new V.Formatter();voiceList.forEach(v=>formatter.joinVoices([v]));const minimum=formatter.preCalculateMinTotalWidth(voiceList);const available=Math.max(60,staveList[0].getNoteEndX()-start-14);formatter.format(voiceList,Math.max(available,minimum));
