function render(){syncControls();try{renderScore()}catch(e){console.error(e);$('score').innerHTML='<p class="render-error">The score could not be displayed. Your notes are still saved. Try Undo or save your song.</p>';toast('Notation could not be drawn: '+e.message)}}
function point(e){const svg=e.currentTarget,r=svg.getBoundingClientRect(),v=svg.viewBox.baseVal;return{x:(e.clientX-r.left)*v.width/r.width,y:(e.clientY-r.top)*v.height/r.height}}
function areaAt(svg,p){return layouts.find(a=>a.svg===svg&&p.x>=a.x&&p.x<a.right&&p.y>=a.top&&p.y<=a.bottom)}
function stepAt(a,y){const base=a.clef==='bass'?18:30;return Math.max(14,Math.min(48,base+Math.round((a.staffBottom-y)/5)))}
function ghost(svg,a,step){const g=svg.querySelector('.ghost');g.innerHTML='';const base=a.clef==='bass'?18:30,y=a.staffBottom-(step-base)*5,x=drag?.view?.x||a.appendX;for(let ly=a.staffBottom+10;ly<=y;ly+=10)g.append(node('line',{x1:x-11,x2:x+11,y1:ly,y2:ly,stroke:'#649780'}));for(let ly=a.staffTop-10;ly>=y;ly-=10)g.append(node('line',{x1:x-11,x2:x+11,y1:ly,y2:ly,stroke:'#649780'}));g.append(node('ellipse',{cx:x,cy:y,rx:6,ry:4,transform:`rotate(-20 ${x} ${y})`,fill:'#548f72',opacity:.7}));g.append(node('text',{x:x+12,y:y-9,'font-family':'Arial','font-size':11,fill:'#4b785f'},M.pitchName({step,acc})));}
function onMove(e){if(playing||e.pointerType==='touch'&&!drag)return;const p=point(e),a=drag?.view?.area||areaAt(e.currentTarget,p);if(!a)return;if(drag?.view){drag.step=stepAt(a,p.y);drag.moved=Math.abs(p.y-drag.y)>4;ghost(e.currentTarget,a,drag.step)}else if(mode==='write'&&!rest&&!e.target.dataset.note&&M.used(song,a.m,a.t)<M.capacity(song)){ghost(e.currentTarget,a,stepAt(a,p.y))}else e.currentTarget.querySelector('.ghost').innerHTML=''}
