function editValue(field,value){const ev=current();if(ev){change(()=>{ev[field]=value;if(M.used(song,selected.m,selected.t)>M.capacity(song))throw Error('That value would overfill this measure. Choose a shorter value.');});const actual=current();if(actual){duration=actual.duration;dot=actual.dot;rest=actual.rest}}else{if(field==='duration')duration=value;if(field==='dot')dot=value;}syncControls()}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;syncControls();if(current()&&(mode==='lyrics'||mode==='chords'))focusText()});document.querySelectorAll('[data-duration]').forEach(b=>b.onclick=()=>editValue('duration',+b.dataset.duration));$('dotBtn').onclick=()=>editValue('dot',!dot);$('restBtn').onclick=()=>{rest=!rest;selected=null;render()};document.querySelectorAll('[data-acc]').forEach(b=>b.onclick=()=>{acc=acc===b.dataset.acc?null:b.dataset.acc;if(current()&&!current().rest)change(()=>current().pitches.forEach(p=>p.acc=acc));syncControls()});$('undoBtn').onclick=undo;$('redoBtn').onclick=redo;
$('fillBtn').onclick=()=>change(()=>{M.fill(song,active.m,active.t);selected=null});$('barline').onchange=e=>change(()=>song.measures[active.m].bar=e.target.value);
function addMeasure(insert){if(song.measures.length>=128)return toast('This sketchbook supports up to 128 measures.');change(()=>{const m=insert?active.m+1:song.measures.length;song.measures.splice(m,0,M.blank());active.m=m;selected=null});if(!insert)setTimeout(()=>$('addMeasure').scrollIntoView({behavior:'smooth',block:'end'}),0)}
$('addMeasure').onclick=()=>addMeasure(false);$('insertMeasure').onclick=()=>addMeasure(true);$('removeMeasure').onclick=()=>showDialog('Delete this measure?',`<p>Remove measure ${active.m+1}, including its notes and text? You can undo this change.</p>`,()=>change(()=>{song.measures.splice(active.m,1);selected=null}),'Delete measure');
$('deleteBtn').onclick=()=>{if(selected)change(()=>{song.measures[selected.m].tracks[selected.t].splice(selected.i,1);selected=null})};$('tieBtn').onclick=()=>{const ev=current();if(!ev||ev.rest)return;if(ev.tie)return change(()=>ev.tie=false);const n=M.next(song,selected.m,selected.t,selected.i);if(!n||!M.samePitch(song,selected,n))return toast('A tie needs the same pitch or chord on the next note.');if(n.m!==selected.m&&M.used(song,selected.m,selected.t)!==M.capacity(song))return toast('Finish this measure before tying across its barline.');change(()=>ev.tie=true)};
function textCommit(id,field){const ev=current();if(ev&&ev[field]!==$(id).value)change(()=>ev[field]=$(id).value)}
for(const [id,field]of [['lyricInput','lyric'],['chordInput','chord']]){$(id).onchange=()=>textCommit(id,field);$(id).onkeydown=e=>{if(e.key==='Enter'||e.key==='Tab'||(field==='lyric'&&(e.key===' '||e.key==='-'))){e.preventDefault();if(e.key==='-'&&!$(id).value.endsWith('-'))$(id).value+='-';textCommit(id,field);advanceText(id)}}}
function advanceText(id){if(!selected)return;let n=M.next(song,selected.m,selected.t,selected.i);while(n&&song.measures[n.m].tracks[n.t][n.i].rest)n=M.next(song,n.m,n.t,n.i);if(n){selected=n;active={m:n.m,t:n.t};render();$(id).value=current()[id==='lyricInput'?'lyric':'chord'];$(id).focus();$(id).select()}else toast('You’ve reached the last note. Add more notes to continue.')}
Object.keys(M.KEYS).sort((a,b)=>M.KEYS[a]-M.KEYS[b]).forEach(k=>{const op=document.createElement('option');op.value=k;op.textContent=`${k.replace('b','♭').replace('#','♯')} major`;$('key').append(op)});
for(const id of ['title','composer']){$(id).onchange=()=>change(()=>song[id]=$(id).value.trim()||(id==='title'?'Untitled idea':''));}
$('tempo').onchange=()=>{const n=Number($('tempo').value);if(!Number.isFinite(n)||n<30||n>240){$('tempo').value=song.tempo;toast('Choose a tempo from 30 to 240.')}else change(()=>song.tempo=n)};
$('key').onchange=e=>change(()=>song.key=e.target.value);
$('meter').onchange=e=>{const next=e.target.value;const trial={...song,meter:next};if(song.measures.some(m=>m.tracks.some(tr=>tr.reduce((n,e)=>n+M.ticks(e),0)>M.capacity(trial)))){e.target.value=song.meter;return toast('Some measures are too full for that meter. Shorten them first.')}change(()=>song.meter=next)};
$('staff').onchange=e=>{const next=e.target.value;if(song.staff==='grand'&&next!=='grand'&&song.measures.some(m=>m.tracks[1].length)){e.target.value=song.staff;showDialog('Switch to a single staff?','<p>The bass part will be kept in your song, but hidden until you choose grand staff again.</p>',()=>change(()=>{song.staff=next;active.t=0;selected=null}),'Switch staff')}else change(()=>{song.staff=next;active.t=0;selected=null})};
function download(){const blob=new Blob([JSON.stringify(song,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=(song.title.replace(/[^a-z0-9 _-]/gi,'').trim()||'My song')+'.music.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Song saved. Use Open to continue writing later.')}
$('saveBtn').onclick=download;$('openBtn').onclick=()=>$('fileInput').click();$('fileInput').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>2e6)return toast('Please choose a song file smaller than 2 MB.');try{const loaded=M.validate(JSON.parse(await f.text()));showDialog('Open this song?',`<p>Open “${escapeHTML(loaded.title)}”? Your current draft can be recovered with Undo.</p>`,()=>change(()=>{song=loaded;selected=null;active={m:0,t:0}}),'Open song')}catch(err){toast('Could not open song: '+err.message)}};
$('newBtn').onclick=()=>showDialog('A fresh page?','<p>Start a new song with four empty measures. Save your current song first if you want a separate copy. You can also undo this change.</p>',()=>change(()=>{song=M.fresh();active={m:0,t:0};selected=null;duration=4;rest=false;dot=false;acc=null;mode='write'}),'Start new song');
$('printBtn').onclick=()=>{stop();document.activeElement?.blur();window.print()};
$('exampleBtn').onclick=()=>showDialog('Try a little melody?','<p>Load a four-measure sketch with lyrics, chord symbols, and a bass part. Your current draft can be recovered with Undo.</p>',()=>change(()=>{song=M.fresh();song.title='A little beginning';song.composer='A sketch to make your own';song.staff='grand';song.tempo=96;const pitches=[[28,30,32,30],[31,30,29,28],[33,32,30,29],[28]];const lyrics=[['Here','is','a','lit-'],['tle','song','to','sing'],['Let','your','i-','deas'],['ring']];pitches.forEach((ps,m)=>{ps.forEach((step,i)=>M.append(song,m,0,{rest:false,pitches:[{step,acc:null}],duration:m===3?1:4,dot:false,lyric:lyrics[m][i],chord:i===0?['C','F','G7','C'][m]:'',tie:false}));M.append(song,m,1,{rest:false,pitches:[{step:[21,17,18,21][m],acc:null}],duration:1,dot:false,lyric:'',chord:'',tie:false})});song.measures[3].bar='end';active={m:0,t:0};selected=null}),'Load melody');
$('helpBtn').onclick=()=>showDialog('A few simple tools',`<p><b>Write:</b> choose a note value and click a pitch on an empty part of the staff. Notes are added in order. Faint rests show unused space and disappear as you write.</p><p><b>Edit:</b> click a note, then change its value or accidental. Drag vertically to change pitch. Shift-click at a different pitch to add a chord tone.</p><p><b>Lyrics & chords:</b> choose the tool, click a note, and type in Note Details. Space or hyphen advances lyrics; Enter advances chord symbols.</p><p><kbd>1–5</kbd> note values · <kbd>R</kbd> rest · <kbd>N</kbd> write · <kbd>V</kbd> select · <kbd>↑ ↓</kbd> pitch · <kbd>Delete</kbd> remove · <kbd>Space</kbd> play/stop · <kbd>Ctrl/⌘ Z</kbd> undo.</p><p><b>Score zoom:</b> use −/＋ or the percentage menu to enlarge notes, lyrics, and chord symbols. Your zoom is remembered on this device. Expand score hides the details panel for more writing space. Wide measures can be scrolled sideways. Printing uses normal page sizing.</p><p><b>Save song</b> downloads an editable song file. Print / PDF opens your browser’s print dialog. This first version has one rhythmic voice per staff. Tempo always counts quarter notes, including in 6/8.</p>`,null);
async function getAudio(){if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')await audio.resume();return audio}
function piano(midi,when,length,gain=.18){const f=440*Math.pow(2,(midi-69)/12),out=audio.createGain();out.gain.setValueAtTime(0,when);out.gain.linearRampToValueAtTime(gain,when+.008);out.gain.exponentialRampToValueAtTime(Math.max(.006,gain*.15),when+Math.min(length,.7));out.gain.exponentialRampToValueAtTime(.0001,when+length+.18);out.connect(audio.destination);const parts=[[1,1],[2,.28],[3,.12],[4,.045]];let left=parts.length;for(const [ratio,amp]of parts){const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=f*ratio;g.gain.value=amp;o.connect(g);g.connect(out);o.start(when);o.stop(when+length+.21);sources.push(o);o.onended=()=>{o.disconnect();g.disconnect();sources=sources.filter(x=>x!==o);if(!--left)out.disconnect()}}}
async function auditionEvent(loc){if(playing||!loc)return;const ev=song.measures[loc.m]?.tracks[loc.t]?.[loc.i];if(!ev||ev.rest)return;try{await getAudio();ev.pitches.forEach(p=>piano(M.midi(song,loc.m,loc.t,loc.i,p),audio.currentTime+.01,.3,.14/Math.sqrt(ev.pitches.length)))}catch{toast('Sound isn’t available in this browser.')}}
function stop(){playing=false;clearTimeout(playTimer);cancelAnimationFrame(playAnimation);sources.forEach(s=>{try{s.stop()}catch{}});sources=[];document.querySelectorAll('.playhead').forEach(g=>g.innerHTML='');$('playBtn').textContent='▶ Play';$('playBtn').setAttribute('aria-label','Play song');document.body.classList.remove('audio-playing')}
async function play(){if(playing){stop();return}try{await getAudio();stop();playing=true;playFrom=startAtActive?active.m:0;const tl=M.timeline(song,playFrom);playEvents=tl.events;playOrigin=audio.currentTime+.1;let next=0;const sounding=playEvents.filter(e=>e.sound).sort((a,b)=>a.time-b.time);function schedule(){if(!playing)return;const now=audio.currentTime-playOrigin;while(next<sounding.length&&sounding[next].time<now+.6){const e=sounding[next++];e.pitches.forEach(p=>piano(p,playOrigin+e.time,Math.max(.05,e.duration-.04),.16/Math.sqrt(e.pitches.length)))}if(now>tl.duration+.3){stop();return}playTimer=setTimeout(schedule,100)}schedule();$('playBtn').textContent='■ Stop';$('playBtn').setAttribute('aria-label','Stop playback');document.body.classList.add('audio-playing');let lastMeasure=-1;function frame(){if(!playing)return;const now=audio.currentTime-playOrigin;document.querySelectorAll('.playhead').forEach(g=>g.innerHTML='');for(const e of playEvents){if(now>=e.time&&now<e.time+M.ticks(song.measures[e.m].tracks[e.t][e.i])*60/song.tempo/8){const v=noteViews.get(e.id);if(v){const g=v.svg.querySelector('.playhead');g.append(node('rect',{x:v.x-13,y:Math.min(...v.ys)-14,width:27,height:Math.max(...v.ys)-Math.min(...v.ys)+28,rx:6,fill:'#81b098',opacity:.3}));if(lastMeasure!==e.m&&e.t===0){lastMeasure=e.m;const r=v.svg.getBoundingClientRect();if(r.bottom>window.innerHeight||r.top<100)v.svg.scrollIntoView({block:'center',behavior:'smooth'})}}}}playAnimation=requestAnimationFrame(frame)}frame()}catch(err){stop();toast('Playback could not start. Try clicking Play again.')}}
function syncZoomControls(){$('scoreZoom').value=String(scoreZoom);$('zoomOut').disabled=scoreZoom<=75;$('zoomIn').disabled=scoreZoom>=300;}
function setScoreZoom(value){const n=Number(value);if(!Number.isFinite(n))return;scoreZoom=Math.max(75,Math.min(300,Math.round(n/25)*25));drag=null;stop();try{localStorage.setItem('drew-music-sketchbook-zoom',String(scoreZoom))}catch{}syncZoomControls();renderScore();}
$('zoomOut').onclick=()=>setScoreZoom(scoreZoom-25);$('zoomIn').onclick=()=>setScoreZoom(scoreZoom+25);$('scoreZoom').onchange=e=>setScoreZoom(e.target.value);
$('wideScore').onclick=()=>{const expanded=document.body.classList.toggle('score-expanded');$('wideScore').textContent=expanded?'Show details':'Expand score';$('wideScore').setAttribute('aria-pressed',String(expanded));$('wideScore').classList.toggle('active',expanded);stop();renderScore();};
$('playBtn').onclick=play;$('fromBtn').onclick=()=>{startAtActive=!startAtActive;syncControls()};
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$('dialog').open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();download();return}if(!e.ctrlKey&&!e.metaKey&&['+','=','-','_'].includes(e.key)){e.preventDefault();setScoreZoom(scoreZoom+(['+','='].includes(e.key)?25:-25))}else if(e.key===' '){e.preventDefault();play()}else if(['1','2','3','4','5'].includes(e.key))editValue('duration',[1,2,4,8,16][+e.key-1]);else if(e.key.toLowerCase()==='r')$('restBtn').click();else if(e.key.toLowerCase()==='n'){mode='write';selected=null;render()}else if(e.key.toLowerCase()==='v'){mode='select';syncControls()}else if(e.key==='Escape'){selected=null;stop();render()}else if((e.key==='Delete'||e.key==='Backspace')&&selected){e.preventDefault();$('deleteBtn').click()}else if(['ArrowUp','ArrowDown'].includes(e.key)&&current()&&!current().rest){e.preventDefault();change(()=>current().pitches.forEach(p=>p.step=Math.max(14,Math.min(48,p.step+(e.key==='ArrowUp'?1:-1)))));auditionEvent(selected)}});
let resizeTimer,lastWidth=0;new ResizeObserver(()=>{const w=$('score').clientWidth;if(Math.abs(w-lastWidth)>4){lastWidth=w;clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{stop();renderScore()},100)}}).observe($('score'));
window.addEventListener('beforeprint',()=>{printing=true;stop();renderScore()});window.addEventListener('afterprint',()=>{printing=false;renderScore()});
window.addEventListener('pagehide',()=>{try{localStorage.setItem('drew-music-sketchbook-v1',JSON.stringify(song))}catch{}});
document.querySelectorAll('[data-duration]').forEach(b=>{const d=+b.dataset.duration,open=d<=2;const head=`<ellipse cx="10" cy="24" rx="6.2" ry="4.2" transform="rotate(-20 10 24)" fill="${open?'none':'currentColor'}" stroke="currentColor" stroke-width="1.7"/>`;const stem=d>1?'<path d="M15.5 23V3" stroke="currentColor" stroke-width="1.6" fill="none"/>':'';const flags=d>=8?'<path d="M16 3 Q29 10 20 19 Q24 10 16 9Z" fill="currentColor"/>'+(d>=16?'<path d="M16 9 Q29 16 20 25 Q24 16 16 15Z" fill="currentColor"/>':''):'';b.querySelector('.music-value').innerHTML=`<svg width="28" height="31" viewBox="0 0 28 31" aria-hidden="true">${head}${stem}${flags}</svg>`});
render();if(!storageOK)$('saveStatus').textContent='Use Save song to keep your work';
